$config=['enabled'=>true,'product'=>'supervision','seller'=>'123','buyer'=>'test_user_fixture@testuser.com','amount'=>20000,'url'=>'https://repotools-desarrollo.onrender.com','plan'=>'sup-plan'];$remote=['id'=>'old-sub','collector_id'=>123,'external_reference'=>'old-reference','status'=>'cancelled','preapproval_plan_id'=>'sup-plan','auto_recurring'=>['frequency'=>1,'frequency_type'=>'months','currency_id'=>'ARS','transaction_amount'=>200]];$payment='rejected';$incomplete=false;$calls=0;
$transport=function($method,$path)use(&$remote,&$payment,&$calls,&$incomplete){retry_ok($method==='GET','Restart never creates a charge');$calls++;if($path==='/users/me')return ['id'=>123,'tags'=>['test_user']];if($path==='/preapproval/'.$remote['id'])return $remote;if(str_starts_with($path,'/preapproval/search?'))return ['results'=>[$remote]];if(str_starts_with($path,'/authorized_payments/search?')){retry_ok(str_ends_with($path,'&limit=5&offset=0'),'Supported provider pagination');return ['results'=>[['preapproval_id'=>'old-sub','payment'=>['status'=>$payment]]],'paging'=>['total'=>$incomplete?6:1]];}throw new RuntimeException('Unexpected resource');};
