$payment='approved';retry_denied(fn()=>$svc->restart(1));$payment='pending';retry_denied(fn()=>$svc->restart(1));$payment='rejected';$remote['status']='authorized';retry_denied(fn()=>$svc->restart(1));$remote['status']='cancelled';$incomplete=true;retry_denied(fn()=>$svc->restart(1));$incomplete=false;$svc->restart(1);$fresh=$db->query('SELECT * FROM supervision_subscriptions WHERE user_id=1')->fetch();retry_ok($fresh['reference']!=='old-reference'&&$fresh['status']==='new'&&$fresh['provider_id']===null,'Fresh independent attempt');retry_ok((int)$db->query('SELECT COUNT(*) FROM billing_cancelled_attempts')->fetchColumn()===1,'Original archived');$n=$calls;$svc->restart(1);retry_ok($calls===$n,'Duplicate restart is idempotent');$old=json_decode($db->query('SELECT snapshot FROM billing_cancelled_attempts')->fetchColumn(),true);retry_ok($old['provider_id']==='old-sub','History preserved');retry_ok((int)$fresh['paid_until']===0,'No entitlement from retry');
$db->exec("UPDATE supervision_subscriptions SET status='cancelled',provider_id='old-sub',paid_until=".(time()+1000));retry_denied(fn()=>$svc->restart(1));
$db->exec("INSERT INTO supervisor_teams(owner_id,name,billing_required,name_pending) VALUES(1,'Mi equipo',1,1),(2,'Otro equipo',0,0)");$svc->nameTeam(1,'Equipo Centro');retry_ok($db->query('SELECT name FROM supervisor_teams WHERE owner_id=1')->fetchColumn()==='Equipo Centro','Own name saved');retry_ok((int)$db->query('SELECT name_pending FROM supervisor_teams WHERE owner_id=1')->fetchColumn()===0,'Onboarding completed');retry_ok($db->query('SELECT name FROM supervisor_teams WHERE owner_id=2')->fetchColumn()==='Otro equipo','Other team unchanged');$db->exec('UPDATE supervision_subscriptions SET paid_until=0');try{$svc->nameTeam(1,'No permitido');throw new RuntimeException('Unpaid naming should fail');}catch(CatalogException $e){retry_ok($e->status===403,'Paid access required');}
echo "OK retry: provider cancellation verified, approved/pending blocked, independent reference, archived history, no charge, duplicate safe, paid team naming and ownership.\n";

